                elif alpha == 1:  # y-component
                    momentum[alpha, q, nu] = 2 * np.imag(np.sum(polar_vec[q, nu, :, 2].conj() * polar_vec[q, nu, :, 0]))
                elif alpha == 2:  # z-component
                    momentum[alpha, q, nu] = 2 * np.imag(np.sum(polar_vec[q, nu, :, 0].conj() * polar_vec[q, nu, :, 1]))

