def Rlnm(l, n, m, k, z, N_t):
    from scipy.special import sph_bess1
    from numpy import sqrt, pi

    if l < abs(m) or n < abs(m):
        return 0

    if m == 0:
        jl = sph_bess1(l, k * z)
        return (-1)**l * sqrt(2*l + 1) * jl

    a_coeff = lambda n, m: sqrt((n+1+abs(m))*(n+1-abs(m))/((2*n+1)*(2*n+3))) if n >= abs(m) else 0
    b_coeff = lambda n, m: sqrt((n-m-1)*(n-m)/((2*n-1)*(2*n+1))) if 0 <= m <= n else -sqrt((n-m-1)*(n-m)/((2*n-1)*(2*n+1))) if -n <= m < 0 else 0

    Rlmn = np.zeros((N_t, N_t), dtype=complex)
    for l in range(N_t):
        for n in range(N_t):
            if m == 0:
                jl = sph_bess1(l, k * z)
                Rlmn[l, n] = (-1)**l * sqrt(2*l + 1) * jl if l == n else 0
            else:
                if l == m + 1:
                    Rlmn[l, m+1] = b_coeff(l, -m-1) * Rlmn[l-1, m] - b_coeff(l+1, m) * Rlmn[l+1, m]
                else:
                    Rlmn[l, n-1] = a_coeff(n-1, m) * Rlmn[l, n-1] - a_coeff(n, m) * Rlmn[l, n+1]
                    Rlmn[l, n+1] = a_coeff(l, m) * Rlmn[l+1, n] - a_coeff(l-1, m) * Rlmn[l-1, n]

    return Rlmn[l, n]
