def apply_channel(K, rho, sys=None, dim=None):
    if dim is None:
        dim = [rho.shape[0]]
    if sys is None:
        sys = list(range(len(dim)))

    full_dim = np.prod(dim)
    identity_matrix = np.eye(full_dim, dtype=float)

    for k in K:
        operator = np.eye(full_dim, dtype=float)
        for i, d in enumerate(dim):
            if i in sys:
                operator = np.kron(operator, k)
            else:
                operator = np.kron(operator, np.eye(d, dtype=float))

        operator = operator.reshape((full_dim, full_dim))
        identity_matrix += np.dot(operator, rho).dot(operator.conj().T)

    return identity_matrix
